INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('195ce771-9c60-5602-bd31-cc675ff1a46b', '0a6e9ce7-65be-50b2-bfc5-6dde97d35702', 'en', $h$Mechanical Oil Gun – 4105$h$, $h$mechanical-oil-gun-4105$h$, NULL, $h$<div> <div><p><strong>Why the 4105 Mechanical Oil Gun?</strong></p><p>You can easily dispense oils, lubricants, and antifreeze solutions at the end of the hose assembly. These guns deliver reliable performance. Their lightweight, ergonomically designed aluminum bodies give you comfortable handling, and a soft-grip trigger adds to your comfort. An inlet filter is also included. You must press the safety latch before you start dispensing the product. When you want to dispense large volumes, you can lock the trigger in the open position.</p><div><div> </div></div></div> </div>$h$, NULL, $h$Mechanical Oil Gun – 4105 | HD Marine$h$, $h$Why the 4105 Mechanical Oil Gun? You can easily dispense oils, lubricants, and antifreeze solutions at the end of the hose assembly. These guns deliver…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b7a94854-7c9c-5cc0-b9fc-84e701c561b8', 'ec4eb442-9517-5fe3-a1a2-49e84714b212', 'en', $h$Mechanical Oil Gun – 4101$h$, $h$mechanical-oil-gun-4101$h$, NULL, $h$<div> <div><p><strong>Why the 4101 Mechanical Oil Gun?</strong></p><p>Its plastic body construction offers a long service life thanks to its aluminum tube, while its ergonomic design provides comfortable use.</p></div> </div>$h$, NULL, $h$Mechanical Oil Gun – 4101 | HD Marine$h$, $h$Why the 4101 Mechanical Oil Gun? Its plastic body construction offers a long service life thanks to its aluminum tube, while its ergonomic design provides…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('30cb763d-dc9e-5134-90f8-5d7a3d9fddd0', '2e831a83-a6a4-5f09-b5b2-1b5c28f4ede9', 'en', $h$Metered Grease Gun – 2306S$h$, $h$metered-grease-gun-2306s$h$, NULL, $h$<div> <div><p><strong>Why the 2306S Metered Grease Gun?</strong></p><p>With the metered grease gun, you can see the amount of grease you pump instantly and precisely on the LCD display. The meter features a total that you can reset after each dispense and a grand total that cannot be reset. Thanks to its compact size and lightweight construction, you can use it in place of a standard grease gun. You can also use it together with pneumatic, electric, or hydraulic greasing equipment. It is an ideal choice especially for high-cost and precision lubrication jobs.</p></div> </div>$h$, NULL, $h$Metered Grease Gun – 2306S | HD Marine$h$, $h$Why the 2306S Metered Grease Gun? With the metered grease gun, you can see the amount of grease you pump instantly and precisely on the LCD display. The…$h$, 'auto') ON CONFLICT DO NOTHING;
