INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('d4e8f60c-b6b3-5ff8-b71a-9c3d860a9278', '5edb5082-4007-5a7a-ab43-78927f19d573', 'en', $h$Quick Grease Coupler – 43545$h$, $h$quick-grease-coupler-43545$h$, NULL, $h$<div> <div><h4><strong>Why the 43545 Quick Grease Coupler?</strong></h4><div><div><div><div><div><div><div><div>We designed the Quick Grease Coupler with a 17 mm connection tip and a 6-point jaw design so you can lubricate grease fittings quickly and easily. This design allows use on all grease fitting profiles. You can also use it with all mechanical and air-operated grease pump models.</div></div></div></div></div></div></div></div></div> </div>$h$, NULL, $h$Quick Grease Coupler – 43545 | HD Marine$h$, $h$Why the 43545 Quick Grease Coupler? We designed the Quick Grease Coupler with a 17 mm connection tip and a 6-point jaw design so you can lubricate grease…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('310b524f-542b-52ef-9f56-5f26a3622d14', 'a096a04b-cfe4-5715-9ead-0dcba724fcd4', 'en', $h$Grease Needle Nozzle – 2075$h$, $h$grease-needle-nozzle-2075$h$, NULL, $h$<div> <div><p><strong>Why the 2075 Grease Needle Nozzle?</strong></p><p>You use the grease needle nozzle with all types of grease guns to inject grease into closed grease fittings. You attach the fitting behind the needle nozzle by pressing it onto the grease coupler on your grease gun.</p></div> </div>$h$, NULL, $h$Grease Needle Nozzle – 2075 | HD Marine$h$, $h$Why the 2075 Grease Needle Nozzle? You use the grease needle nozzle with all types of grease guns to inject grease into closed grease fittings. You attach…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('83c1d5b7-2456-5c12-b9ed-4a3fa44784c3', '7e3717db-44fa-56e5-9e3c-a8c1d380746c', 'en', $h$Grease Coupler – 2045$h$, $h$grease-coupler-2045$h$, NULL, $h$<div> <div><p><strong>Why the 2045 Grease Coupler?</strong></p><p>The grease coupler carries jaws that we hardened for a good grip. This ensures maximum safety and efficiency while you use it. Its design offers full compatibility with pneumatic or mechanical grease gun models. So you attach it easily and finish your lubrication jobs effortlessly.</p></div> </div>$h$, NULL, $h$Grease Coupler – 2045 | HD Marine$h$, $h$Why the 2045 Grease Coupler? The grease coupler carries jaws that we hardened for a good grip. This ensures maximum safety and efficiency while you use…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('89e398c0-52e0-5e42-87bf-cfc66e032e2d', '2879605d-cfb4-56a4-adf8-231d207f6a27', 'en', $h$Pneumatic Grease Transfer Pump – 2460$h$, $h$pneumatic-grease-transfer-pump-2460$h$, NULL, $h$<div> <div><p><strong>Why the 2460 Pneumatic Grease Transfer Pump?</strong></p><p>The pneumatic grease transfer pump transfers grease and similar lubricants from the drum in a short time. The pressure of the supplied air affects the pump's output. The viscosity and temperature of the fluid also change the output. Hose and connection sizes also affect pump performance. Keep the operating pressure between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. We make the piston diameter Ø58 mm. We integrated a drum connection so you can easily mount the pump on the drum. These pumps require certain accessories to operate at full efficiency. We offer recommendations in the products section, where you will find the accessories.</p></div> </div>$h$, NULL, $h$Pneumatic Grease Transfer Pump – 2460 | HD Marine$h$, $h$Why the 2460 Pneumatic Grease Transfer Pump? The pneumatic grease transfer pump transfers grease and similar lubricants from the drum in a short time. The…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('84350287-48fe-5544-bc07-8e50adea995b', '753f544e-2f89-5d8e-a001-10db530869b6', 'en', $h$Pneumatic Oil Transfer Pump – 1035$h$, $h$pneumatic-oil-transfer-pump-1035$h$, NULL, $h$<div> <div><p><strong>Why the 1035 Pneumatic Oil Transfer Pump?</strong></p><p>The pneumatic light oil transfer pump transfers low and medium viscosity oils in a short time. Its stainless steel models also allow you to transfer different fluids. The pressure of the supplied air affects the pump's output. The viscosity and temperature of the fluid also change the output. Hose and connection sizes also affect pump performance. Keep the operating pressure between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. We make the piston diameter Ø58 mm. We integrated a drum connection so you can easily mount the pump on the drum. These pumps require certain accessories to operate at full efficiency. We offer recommendations in the products section, where you will find the accessories.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Transfer Pump – 1035 | HD Marine$h$, $h$Why the 1035 Pneumatic Oil Transfer Pump? The pneumatic light oil transfer pump transfers low and medium viscosity oils in a short time. Its stainless…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('95546f2e-220f-53a3-a5ab-03035ecd33e0', '27ea41fb-1660-501c-aef1-eb4312044559', 'en', $h$Pneumatic Oil Transfer Pump – 1005$h$, $h$pneumatic-oil-transfer-pump-1005$h$, NULL, $h$<div> <div><p><strong>Why the 1005 Pneumatic Oil Transfer Pump?</strong></p><p>The pneumatic light oil transfer pump transfers low and medium viscosity oils in a short time. Its stainless steel models also allow you to transfer different fluids. The pump's output is affected by the air pressure and by the viscosity and temperature of the fluid. Hose and connection sizes also change application efficiency. Keep the operating pressure between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. We make the piston diameter Ø58 mm. The pump includes a special connection for easy mounting on the drum. The pump uses certain accessories to operate at full efficiency. We recommend these accessories in the products section, where you will find them.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Transfer Pump – 1005 | HD Marine$h$, $h$Why the 1005 Pneumatic Oil Transfer Pump? The pneumatic light oil transfer pump transfers low and medium viscosity oils in a short time. Its stainless…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('56756e6c-fdb0-5c01-9d5f-7d952a637333', 'bccf524e-55d6-5292-bfae-0627191481a6', 'en', $h$IBC Oil System with Hose Reel – IBC4500$h$, $h$ibc-oil-system-with-hose-reel-ibc4500$h$, NULL, $h$<div> <div><p><strong>Why the IBC4500 IBC Oil System with Hose Reel?</strong></p><p>We designed IBC oil systems to make work easier for businesses with high-capacity oil needs. You can use different combinations in the system; you can choose metered or non-metered oil guns, reels with 10-15-20 meter hose winding capacity, and pneumatic pumps with different outputs.</p><p><a href="https://www.gulersan.com/wp-content/uploads/2021/01/IBC4500.jpg"><img alt="IBC Oil System with Hose Reel IBC4500. A high-pressure pneumatic pump system with hose reel for oil transfer from IBC tanks, providing organized and efficient bulk oil dispensing." src="https://www.gulersan.com/wp-content/uploads/2021/01/IBC4500.jpg"/></a></p></div> </div>$h$, NULL, $h$IBC Oil System with Hose Reel – IBC4500 | HD Marine$h$, $h$Why the IBC4500 IBC Oil System with Hose Reel? We designed IBC oil systems to make work easier for businesses with high-capacity oil needs. You can use…$h$, 'auto') ON CONFLICT DO NOTHING;
